APP='https://play.google.com/store/apps/details?id=com.FinalAstroTry.app'
def promotion(prefix='',lang='hi'):
 hi=lang=='hi';home='index.html' if hi else 'english.html';num='numerology.html' if hi else 'numerology-english.html'
 return f'''<aside class="av-promotion" aria-label="{'AstroVedansh के साथ आगे सीखें' if hi else 'Continue learning with AstroVedansh'}"><div class="av-promotion-inner"><div><span class="av-promotion-label">{'सीखें · समझें · अभ्यास करें' if hi else 'LEARN · UNDERSTAND · PRACTISE'}</span><h2>{'आज सीखे सूत्र को अपनी कुंडली पर आजमाएँ।' if hi else 'Put what you learn into practice.'}</h2><p>{'AstroTry पर कुंडली बनाएँ और अध्ययन का अभ्यास करें। व्यवस्थित मार्गदर्शन के लिए अपना पाठ्यक्रम चुनें।' if hi else 'Create a chart with AstroTry and practise your analysis. Choose a course for structured guidance.'}</p></div><div class="av-promotion-actions"><a class="av-promotion-primary" href="{APP}" target="_blank" rel="noopener noreferrer">{'AstroTry ऐप देखें' if hi else 'Explore the AstroTry app'} ↗</a><a href="{prefix}{home}#enrol">{'वैदिक ज्योतिष सीखें' if hi else 'Learn Vedic astrology'} →</a><a href="{prefix}{num}">{'अंकज्योतिष पाठ्यक्रम देखें' if hi else 'Explore the numerology course'} →</a></div></div></aside>'''
